{
  "query": "query { companies { id name website } }"
}

{
  "query": "query SearchCompanies($term: String!) { searchCompanies(searchTerm: $term) { id name website } }",
  "variables": { "term": "Tech" }
}

{
  "query": "mutation CreateCompany($input: CreateCompanyInput!) { createCompany(input: $input) { id name website } }",
  "variables": { "input": { "name": "Global Tech", "website": "https://globaltech.com" } }
}

{
  "query": "mutation UpdateCompany($id: ID!, $input: UpdateCompanyInput!) { updateCompany(id: $id, input: $input) { id name website } }",
  "variables": { "id": "0ed1c181-7107-4e01-ab0e-34a50f2a71ff", "input": { "name": "Global Tech Updated", "website": "https://updated.com" } }
}

{
  "query": "mutation RemoveCompany($id: ID!) { deleteCompany(id: $id)  }",
  "variables": { "id": "0468f683-42dd-438b-8b2e-8c61f7b7f61f" }
}

{
  "query": "query { persons { id firstName lastName email } }"
}

{
  "query": "mutation CreatePerson($input: CreatePersonInput!) { createPerson(input: $input) { id firstName lastName email } }",
  "variables": { "input": { "firstName": "Анна", "lastName": "Смирнова", "email": "anna@example.com" } }
}

{
  "query": "mutation UpdatePerson($id: ID!, $input: UpdatePersonInput!) { updatePerson(id: $id, input: $input) { id firstName lastName email } }",
  "variables": { "id": "59dec001-03e7-4455-a644-e4717c417251", "input": { "firstName": "Анна-Мария" } }
}

{
  "query": "mutation RemovePerson($id: ID!) { deletePerson(id: $id) }",
  "variables": { "id": "4ac52ab3-5704-4702-a4e4-f24b3c4d0153" }
}

{
  "query": "query { profiles { id slug name description links person { firstName lastName email } skills { name category } experiences { position period achievements company { name website } } projects { name url } } }"
}

{
  "query": "query GetProfile($slug: String!) { profileBySlug(slug: $slug) { id slug name description } }",
  "variables": { "slug": "ivan-petrov-backend" }
}

{
  "query": "mutation CreateProfile($input: CreateProfileInput!) { createProfile(input: $input) { id slug name description links } }",
  "variables": { "input": { "slug": "anna-dev", "name": "Анна Смирнова", "description": "Frontend", "personId": "59dec001-03e7-4455-a644-e4717c417251",
    "links": ["https://github.com/anna-dev"] } }
}

{
  "query": "mutation UpdateProfile($id: ID!, $input: UpdateProfileInput!) { updateProfile(id: $id, input: $input) { id name description } }",
  "variables": { "id": "677c7ba0-e9f9-4835-8ab3-24d8dda7e160", "input": { "description": "Senior Frontend Dev" } }
}

{
  "query": "mutation RemoveProfile($id: ID!) { deleteProfile(id: $id) }",
  "variables": { "id": "677c7ba0-e9f9-4835-8ab3-24d8dda7e160" }
}

{
  "query": "query { skills { id name category } }"
}

{
  "query": "mutation CreateSkill($input: CreateSkillInput!) { createSkill(input: $input) { id name category } }",
  "variables": { "input": { "name": "React", "category": "Frontend", "personId": "59dec001-03e7-4455-a644-e4717c417251" } }
}

{
  "query": "mutation UpdateSkill($id: ID!, $input: UpdateSkillInput!) { updateSkill(id: $id, input: $input) { id name category } }",
  "variables": { "id": "3616b2e5-1d43-49ec-a3e4-b630202ba582", "input": { "name": "React.js" } }
}

{
  "query": "mutation RemoveSkill($id: ID!) { deleteSkill(id: $id) }",
  "variables": { "id": "3616b2e5-1d43-49ec-a3e4-b630202ba582" }
}

{
  "query": "query { projects { id name url } }"
}

{
  "query": "mutation CreateProject($input: CreateProjectInput!) { createProject(input: $input) { id name url } }",
  "variables": { "input": { "name": "Dashboard", "url": "https://github.com", "personId": "59dec001-03e7-4455-a644-e4717c417251" } }
}

{
  "query": "mutation UpdateProject($id: ID!, $input: UpdateProjectInput!) { updateProject(id: $id, input: $input) { id name url } }",
  "variables": { "id": "3a91ed55-4b2c-4310-aec2-88202afab009", "input": { "name": "Admin Dashboard" } }
}

{
  "query": "mutation RemoveProject($id: ID!) { deleteProject(id: $id) }",
  "variables": { "id": "3a91ed55-4b2c-4310-aec2-88202afab009" }
}

{
  "query": "query { experiences { id position period } }"
}

{
  "query": "mutation CreateExperience($input: CreateExperienceInput!) { createExperience(input: $input) { id position period achievements } }",
  "variables": { "input": { "position": "Developer", "period": "2024", "personId": "59dec001-03e7-4455-a644-e4717c417251", "companyId": "0ed1c181-7107-4e01-ab0e-34a50f2a71ff",
    "achievements": [
      "Оптимизировал GraphQL-запросы на 40%",
      "Внедрил Docker-инфраструктуру"
    ] } }
}

{
  "query": "mutation UpdateExperience($id: ID!, $input: UpdateExperienceInput!) { updateExperience(id: $id, input: $input) { id position period } }",
  "variables": { "id": "a17d5950-a429-435e-9a71-77375329e03e", "input": { "position": "Senior Developer" } }
}

{
  "query": "mutation RemoveExperience($id: ID!) { deleteExperience(id: $id)  }",
  "variables": { "id": "a17d5950-a429-435e-9a71-77375329e03e" }
}
